code='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comp_size = {}
    # Label 4-connected non-background components. Large components are the real objects.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            for y, x in cells:
                comp_size[y, x] = len(cells)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or comp_size.get((r,c), 0) != 1:
                continue
            neighbors = [grid[y][x] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                         if 0 <= y < h and 0 <= x < w]
            counts = Counter(v for v in neighbors if v != bg and comp_size.get((r + (v==grid[r][c]), c), 0) > 1)
            # Prefer the surrounding non-background object when the pixel lies inside its shape.
            obj = Counter(v for v in neighbors if v != bg and v != grid[r][c])
            if obj and max(obj.values()) >= 2:
                out[r][c] = obj.most_common(1)[0][0]
            else:
                out[r][c] = bg
    return out
